pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let post_norm = post / cap;
    let item_norm = item_size as f64 / cap;

    // Base: prefer tight fits (low post_residual), with non-linear penalty on waste
    let mut score = post * (1.0 + 2.0 * post_norm * post_norm);

    // Smooth stream-progress coupling: early on, tolerate waste (post_norm^3 term);
    // later, penalize waste more aggressively via cubic-polynomial weight
    let w = 1.0 + 3.0 * progress - 2.0 * progress * progress;
    score += w * post_norm * post_norm * cap;

    // Reward filling the bin when it becomes near-perfectly packed
    score -= item_norm * item_norm * cap * (1.0 + progress);

    // Lookahead coupling: if next item fits in post_residual, reward this placement
    if next_item_size > 0 && (next_item_size as u32) <= post_residual {
        score -= 8.0 + 12.0 * progress;
    } else if next_item_size > 0 {
        // Penalize dead space the next item cannot use (smooth in gap size)
        let gap = (next_item_size as f64 - post).max(0.0) / cap;
        score += 10.0 * gap * (1.0 + gap);
    }

    // Last-chance bin: strongly favor using it to avoid opening new bins
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Mild pressure to consolidate when many bins are open
    score += 0.5 * open_bins_count as f64 * post_norm;

    // Deviation from mean residual: prefer bins whose residual is below average (tighter)
    score += 2.0 * (mean_residual - post).max(0.0) * 0.05;

    // New-bin candidate: keep neutral-ish baseline so it wins only when open bins score poorly
    if bin_residual == bin_capacity {
        score = cap * 0.9 + 5.0 * progress - 3.0 * item_norm * cap;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify dead space into capacity fractions
    let cap = bin_capacity as f64;
    let frac = post_residual as f64 / cap; // fraction of capacity left as dead space

    // Penalize post_residuals in "awkward" harmonic classes.
    // Residuals that are multiples of 50 (half-capacity classes) pair well with
    // typical item sizes; odd small residuals (< 10) are dead space.
    let class = post_residual % 50;
    if post_residual == 0 {
        score -= 60.0; // perfect fit: strongly reward
    } else if post_residual < 10 {
        score += 40.0; // tiny unusable dead space: penalize
    } else if class == 0 {
        score -= 25.0; // exact half/full multiple: excellent reusable class
    } else if class <= 20 {
        score -= 10.0; // decent class, common item sizes fit
    } else if class >= 40 {
        score += 12.0; // awkward class just below 50
    }

    // Nonlinear penalty on fraction wasted, steeper as bin gets emptier relative to fill
    score += 15.0 * frac * frac;

    // Lookahead coupling: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size <= post_residual {
            // harmonic check: does next item leave another clean class?
            let next_post = post_residual - next_item_size;
            if next_post % 50 == 0 || next_post == 0 {
                score -= 20.0;
            } else if next_post < 10 {
                score += 15.0;
            }
        } else {
            // next item won't fit here: mild penalty proportional to overshoot class
            let gap = (next_item_size - post_residual) % 50;
            score += 5.0 + (gap as f64) * 0.3;
        }
    } else {
        // last item: prefer zero residual strongly
        score += (post_residual as f64) * 0.5;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Prefer opening a new bin only when all open bins would leave bad dead space.
    if bin_residual == bin_capacity {
        // base cost of a new bin, discounted late in the stream
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 55.0 - 20.0 * progress;
        if post_residual == 0 {
            score -= 60.0;
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // fresh bin is fine if next item is big
        }
    }

    // Mild tie-break toward consolidating among many open bins
    score += (open_bins_count as f64) * 0.15;

    score
}

