            0.0
        };
        score -= 40.0 * (1.0 - gap / bin_capacity as f64);
        // If next item cannot fit in the post residual, mild penalty for
        // leaving a bin that strands the lookahead item.
        if next_item_size > post_residual {
            score += 10.0 * progress;
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly favor it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item is large
    // or many bins are open with low mean residual (fragmentation).
    if bin_residual == bin_capacity {
        let fragmentation = mean_residual / bin_capacity as f64;
        let threshold = 25.0 + 50.0 * (1.0 - fragmentation);
        if (item_size as f64) < threshold && fitting_bins_count > 0 {
            score += 80.0 - 40.0 * progress;
        } else {
            score -= 20.0;
        }
    }

    // Slight preference for bins below mean residual (balance residuals).
    score += 0.05 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits (small post_residual), with quadratic sharpening.
    let mut score = pr * (1.0 + norm_pr);

    // Smooth non-linear coupling: as stream progresses, dead space becomes costlier.
    let dead_weight = 1.0 + progress * norm_pr * (2.0 + progress);
    score *= dead_weight;

    // Last-chance bonus: only one fitting bin -> strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - norm_pr) * (0.5 + progress);
    }

    // Scarcity pressure: many open bins with slack -> penalize low-fill placements mildly.
    let scarcity = (open_bins_count as f64).ln1p();
    score += scarcity * norm_pr * 4.0;

    // Lookahead: if next item fits perfectly in post_residual, reward this placement.
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        let fit_quality = 1.0 - gap / cap;
        if fit_quality > 0.0 {
            score -= 10.0 * fit_quality * fit_quality * (1.0 + progress);
        }
        // Penalize post_residual that is uselessly small for the next item.
        if pr < next_item_size as f64 && pr > 0.0 {
            score += 6.0 * (1.0 - pr / next_item_size as f64) * (0.5 + progress);
        }
    }

    // Relative tightness term vs mean residual across bins.
    let rel = if mean_residual > 0.0 { pr / mean_residual } else { 1.0 };
    score += (rel - 1.0).abs() * 2.0;

    // New-bin candidate: smooth sigmoid gate — open new bin only when fits are poor.
    let is_new = (bin_residual == bin_capacity) as f64;
    let tightness = 1.0 - norm_pr;
    let gate = 1.0 / (1.0 + (-8.0 * (tightness - 0.75)).exp());
    score += is_new * (40.0 * gate - 20.0 * (1.0 - gate));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: prefer residuals that fall into "usable" classes
    // (multiples of small denominators can absorb future items of common sizes).
    let cap = bin_capacity as f64;

    // Fractional fill of the bin after placement
    let fill = 1.0 - (post_residual as f64) / cap;
    score -= 40.0 * fill * fill; // reward tight packing quadratically

    // Dead-space penalty: residuals that are too small to fit typical small items (1..=10)
    if post_residual < 10 && post_residual > 0 {
        score += 25.0;
    }

    // Modulo classes: residuals divisible by 5 or 10 are more likely reusable
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 8.0;
    } else if post_residual % 5 == 0 && post_residual > 0 {
        score -= 4.0;
    } else {
        score += 3.0; // odd/awkward residual class
    }

    // Lookahead coupling: if the next item fits exactly into post_residual, strong reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= 6.0;
        } else {
            score += 5.0; // next item won't fit here; slight penalty for wasting this slot
        }
    }

    // Last-chance bin: if this is the only fitting bin, heavily favor using it
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a new bin is expensive unless the current
    // item leaves a very awkward residual in all open bins.
    if bin_residual == bin_capacity {
        // Brand-new empty bin: baseline cost plus a discount late in the stream
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score = 45.0 - 10.0 * progress;
        // If item is large (harmonic upper class), a fresh bin is more attractive
        if item_size > bin_capacity / 2 {
            score -= 8.0;
        }
    } else if post_residual == 0 {
        // Perfect fit: overwhelming reward
        score -= 100.0;
    }

    // Slight penalty for spreading across many bins when mean residual is high
    score += 0.02 * open_bins_count as f64;
    score -= 0.01 * mean_residual;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for the
    // smallest plausible future item are "dead space". Penalize them hard.
    if post_residual > 0 {
        let dead_threshold: u32 = 10;
        if post_residual <= dead_threshold {
            score += 45.0 * (1.0 - post_residual as f64 / dead_threshold as f64);
        }
    } else {
        // Perfect fill: strongly reward.
        score -= 60.0;
    }

    // Reward tight fits relative to item size.
    score -= (item_size as f64 / bin_capacity as f64) * 20.0;

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: make it attractive only when the item fits poorly
    // everywhere else. An empty bin has residual == capacity, so post_residual
    // is large; give it a mild penalty so tight existing fits win.
    if bin_residual == bin_capacity {
        score += 15.0;
        // But if the item is huge, a fresh bin is often the right call.
        if item_size >= 70 {
            score -= 35.0;
        }
        // Early in the stream, opening bins is cheap and keeps flexibility.
        if total_items > 0 && (step_index as f64) / (total_items as f64) < 0.25 {
            score -= 10.0;
        }
    }

    // Open-bin pressure: many open bins -> prefer consolidating into existing
    // bins rather than opening more (penalize new-bin spread).
    score += (open_bins_count as f64) * 0.8 * (post_residual as f64 / bin_capacity as f64);

    // Lookahead: if the next item can use this bin's post_residual exactly
    // (or nearly), reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack <= 10 {
            score -= 25.0;
        } else {
            score -= 5.0;
        }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Post-residual too small for the known next item: dead space penalty.
        score += 20.0;
    }

    // Prefer bins whose residual is below the mean (tighter bins get used).
    score += (mean_residual - bin_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), with slight super-linear bias.
    let pr = post_residual as f64;
    score = pr + 0.002 * pr * pr;

    // Lookahead: strongly reward bins whose post_residual exactly fits the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if next_item_size == post_residual {
            // Perfect 2-step chain: fill this bin completely.
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // Next item fits: reward closeness of the resulting double-fit.
            let gap = (post_residual as f64 - nxt).abs();
            score -= 25.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // Next item won't fit here: penalize leaving dead space relative to next item.
            let waste = next_item_size as f64 - pr;
            score += 0.35 * waste;
        }
    }

    // Relative-to-mean coupling: bins tighter than average are more valuable to pack now.
    let dev = mean_residual - pr;
    score -= 0.25 * dev;

    // Last-chance bonus: if this is the only bin that can fit the item, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when all open bins are nearly full
    // (their residuals are too small to be useful) or stream is early with few bins.
    if bin_residual == bin_capacity {
        let avg = if open_bins_count > 0 { mean_residual } else { 0.0 };
        if avg < 25.0 || open_bins_count == 0 {
            score -= 30.0; // open bins are nearly exhausted; fresh bin is good
        } else {
            score += 15.0; // discourage abandoning usable open bins
        }
    }

    // Mild late-stream consolidation: as the stream progresses, prefer filling existing bins
    // over spreading items out.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * (pr / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // New-bin candidate: penalize slightly so we only open a new bin when
    // every existing option is genuinely poor (high post_residual / dead space).
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 25.0 + 0.15 * open_bins_count as f64;
        // Late in the stream, prefer closing out existing bins rather than
        // opening new ones (fewer bins at the end matters more).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
        return score;
    }

    // Reward tight fits: small post_residual is good, but a residual so small
    // that nothing can ever use it is dead space — penalize the dead zone.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0; // unusable sliver
    }

    // Lookahead: if the next item fits exactly into the post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            // reward proportionally to how well next item uses leftover space
            let fill = next_item_size as f64 / post_residual as f64;
            score -= 20.0 * fill;
        } else {
            // next item won't fit here; mildly penalize leaving a large gap
            score += 0.1 * (post_residual as f64 - (next_item_size as f64 - post_residual as f64).abs());
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Prefer bins whose residual is below the mean (consolidate waste into few bins).
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Early in the stream, encourage spreading items across bins to build
    // flexible residuals; later, concentrate into tight bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 0.2 * post_residual as f64;

    // Slight preference for bins with larger current residual when many bins open
    // (keeps small bins available for small items).
    score -= 0.05 * bin_residual as f64 / (1.0 + open_bins_count as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let post_norm = post / cap;
    let item_norm = item_size as f64 / cap;

    // Base: prefer tight fits (low post_residual), with non-linear penalty on waste
    let mut score = post * (1.0 + 2.0 * post_norm * post_norm);

    // Smooth stream-progress coupling: early on, tolerate waste (post_norm^3 term);
    // later, penalize waste more aggressively via cubic-polynomial weight
    let w = 1.0 + 3.0 * progress - 2.0 * progress * progress;
    score += w * post_norm * post_norm * cap;

    // Reward filling the bin when it becomes near-perfectly packed
    score -= item_norm * item_norm * cap * (1.0 + progress);

    // Lookahead coupling: if next item fits in post_residual, reward this placement
    if next_item_size > 0 && (next_item_size as u32) <= post_residual {
        score -= 8.0 + 12.0 * progress;
    } else if next_item_size > 0 {
        // Penalize dead space the next item cannot use (smooth in gap size)
        let gap = (next_item_size as f64 - post).max(0.0) / cap;
        score += 10.0 * gap * (1.0 + gap);
    }

    // Last-chance bin: strongly favor using it to avoid opening new bins
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Mild pressure to consolidate when many bins are open
    score += 0.5 * open_bins_count as f64 * post_norm;

    // Deviation from mean residual: prefer bins whose residual is below average (tighter)
    score += 2.0 * (mean_residual - post).max(0.0) * 0.05;

    // New-bin candidate: keep neutral-ish baseline so it wins only when open bins score poorly
    if bin_residual == bin_capacity {
        score = cap * 0.9 + 5.0 * progress - 3.0 * item_norm * cap;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of post_residual: dead-space severity classes ---
    // Items in 1..100; small residuals (<10) are near-perfect fits.
    if post_residual == 0 {
        score -= 50.0; // perfect fit, ideal
    } else if post_residual < 10 {
        score -= 20.0;
    } else if post_residual < 25 {
        score -= 5.0;
    } else if post_residual < 50 {
        score += 8.0;
    } else {
        score += 15.0; // large hole left behind
    }

    // --- Modulo classes: residuals that are multiples of common item sizes are reusable ---
    let pr = post_residual;
    if pr > 0 {
        let mut reuse_bonus = 0.0;
        for m in [10u32, 20, 25, 30, 40, 50] {
            if pr % m == 0 {
                reuse_bonus += 6.0;
            }
        }
        score -= reuse_bonus;
    }

    // --- Lookahead coupling: does this placement leave room for next_item_size? ---
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // next item fits here afterwards: reward, scaled by snugness
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 - (slack / 10.0).min(6.0);
            // exact chain fit is gold
            if post_residual == next_item_size {
                score -= 25.0;
            }
        } else {
            // next item won't fit after this placement: penalize proportionally
            let miss = (next_item_size - post_residual) as f64;
            score += (miss / 10.0).min(20.0);
        }
    } else {
        // last item: any placement is fine, prefer tightest
        score -= 10.0;
    }

    // --- Last-chance bin: if this is the only fitting bin, strongly prefer it ---
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when existing residuals are badly
        // fragmented (high mean residual) or no open bin fits well.
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = (mean_residual - post_residual as f64).max(0.0);
        score += 35.0                      // base reluctance to open new bin
               - fragmentation * 0.6       // reward if open bins are fragmented
               - if fitting_bins_count == 0 { 60.0 } else { 0.0 }
               + progress * 5.0;           // slight late-stream conservatism
        // new bin leaves full residual; judge it by what it offers
        score += (bin_capacity - item_size) as f64 * 0.1;
    }

    // --- Mild preference for filling fuller bins (small residual before placement) ---
    score += (bin_residual as f64) * 0.05;

    // --- Tie-break noise-free harmonic dither on open bins count ---
    score -= (open_bins_count % 3) as f64 * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect fits strongly.
    if post_residual == 0 {
        score -= 500.0;
    }

    // Penalize small unusable dead space (gaps below the minimum item size).
    if post_residual > 0 && post_residual < 10 {
        score += 300.0 * (1.0 - post_residual as f64 / 10.0);
    }

    // Prefer tight fits generally: reward small post_residual non-linearly.
    score += (post_residual as f64 / bin_capacity as f64).powi(3) * 100.0;

    // Last-chance bonus: if this is the only bin that fits, strongly favor it.
    if fitting_bins_count == 1 {
        score -= 200.0;
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += open_bins_count as f64 * 2.0;

    // Penalize bins whose residual deviates far below the mean (fragmentation).
    if (bin_residual as f64) < mean_residual {
        score += (mean_residual - bin_residual as f64) * 0.5;
    }

    // Lookahead: if next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 50.0;
    }

    // New-bin candidate: keep it competitive only when open bins are fragmented.
    if bin_residual == bin_capacity {
        score -= 20.0 + open_bins_count as f64 * 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong 2-step lookahead: reward exact/near-exact chaining of next item into post_residual.
    if next_item_size > 0 && next_item_size <= post_residual {
        let chain_waste = (post_residual - next_item_size) as f64;
        // Perfect chain (post_residual == next_item_size) is heavily rewarded.
        score -= 60.0 * (1.0 - chain_waste / bin_capacity as f64);
        // Extra bonus if the chain leaves a still-usable small gap.
        if chain_waste <= 10.0 {
            score -= 15.0;
        }
    } else if next_item_size > 0 {
        // Next item cannot chain: penalize leaving residual that is too small for typical items.
        if post_residual < 10 {
            score += 40.0; // dead space
        } else {
            score += 10.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Prefer bins whose residual is already below mean (tight bins first).
    let dev = mean_residual - post_residual as f64;
    score += 0.5 * dev;

    // Penalize leaving residual in a narrow unusable band (e.g. 1..=9 after placement).
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // Late in the stream, tighten packing more aggressively (favor fullest bins).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0 * (post_residual as f64 / bin_capacity as f64);

    // Mild penalty when many bins are open: encourage consolidation.
    score += 0.3 * open_bins_count as f64;

    // Brand-new empty bin candidate: only attractive if no open bin fits well
    // (i.e., item is large relative to mean residual).
    if bin_residual == bin_capacity {
        let spread = (post_residual as f64 - mean_residual).abs();
        score = 100.0 + spread * 0.1 - (item_size as f64 / bin_capacity as f64) * 10.0;
        if fitting_bins_count == 0 {
            score -= 200.0; // no alternative, must open new bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly prefer placements that leave little waste.
    let tight = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 60.0 * tight * tight;

    // Exact fit bonus.
    if post_residual == 0 {
        score -= 200.0;
    }

    // Lookahead: reward bins whose leftover can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 25.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Penalize leaving dead space the next item cannot use.
            score += 20.0 * (next_item_size as f64 - post_residual as f64) / 100.0;
        }
    }

    // Last-chance bin: strongly avoid opening a new bin when this is the only fitting one.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // Prefer fuller bins overall (relative to mean residual).
    if (bin_residual as f64) < mean_residual {
        score += 10.0;
    } else {
        score -= 5.0;
    }

    // Late in the stream: consolidate, avoid new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses and as more bins are open.
        score += 40.0 + 60.0 * progress + 2.0 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let r = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_r = r / cap;

    // Base: prefer tight fits, with a smooth polynomial penalty on residual.
    let mut score = r * (1.0 + 0.8 * norm_r * norm_r);

    // Non-linear coupling of residual with stream progress: early on tolerate
    // larger residuals (bins stay flexible), late in the stream penalize them hard.
    let progress_coupling = 1.0 + 2.5 * progress * progress;
    score *= progress_coupling;

    // Smooth interaction: residual vs. mean residual of open bins.
    // A residual far below the mean suggests this bin is becoming dead space.
    let dev = (r - mean_residual) / cap;
    score += 6.0 * dev * dev * (0.5 + progress);

    // Lookahead: reward if the next item fits the post-residual smoothly,
    // penalize near-misses with a smooth ramp.
    if next_item_size > 0 {
        let gap = post_residual as f64 - next_item_size as f64;
        if gap >= 0.0 {
            score -= 4.0 * (1.0 - (gap / cap).min(1.0));
        } else {
            score += 1.5 * (-gap / cap);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    // unless the post-residual is truly terrible (smooth sigmoid-like gate).
    if fitting_bins_count == 1 {
        let badness = 1.0 / (1.0 + (-6.0 * (norm_r - 0.15)).exp());
        score -= 8.0 * (1.0 - badness);
    }

    // Mild penalty for proliferation of open bins late in the stream.
    score += 0.05 * open_bins_count as f64 * progress;

    // Slight nudge to prefer fuller bins over a fresh bin.
    if bin_residual == bin_capacity {
        score += 2.0 + 3.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;

    // Harmonic class of the post residual: modulo classes over common item sizes
    let pr = post_residual;
    let harm = |x: u32| -> f64 {
        if x == 0 {
            0.0 // perfect fit: perfectly closed bin
        } else if x % 10 == 0 {
            0.5 // residual aligned to decile: highly reusable
        } else if x % 5 == 0 {
            1.0 // half-aligned
        } else {
            2.0 // ragged residual
        }
    };
    score += harm(pr) * 3.0;

    // Reward perfect closure
    if pr == 0 {
        score -= 40.0;
    }

    // Lookahead coupling: does post_residual admit the next item?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // next item fits: reward proportional to how snugly
            score -= 8.0 + 10.0 * (next_item_size as f64 / cap);
        } else {
            // dead space for the next item: penalize by gap size class
            let gap = next_item_size - pr;
            score += (gap as f64).min(30.0) * 0.6;
        }
        // harmonic match: next item size shares a modulo class with residual
        if pr % 10 == next_item_size % 10 && next_item_size <= pr {
            score -= 5.0;
        }
    } else {
        // last item: prefer closing bins tightly
        score -= 6.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New empty bin candidate: penalize mildly, unless current bin residual is tiny/ragged
    if bin_residual == bin_capacity {
        score += 15.0;
        if pr == bin_capacity {
            // called on the new bin itself: neutral baseline
            score += (post_residual as f64) - cap;
        }
    }

    // Ragged small residuals are dead space: extra penalty
    if pr > 0 && pr < 10 {
        score += 10.0;
