    score -= 20.0 * (1.0 - gap / bin_capacity as f64);

    // Open-bin pressure: with many open bins, discourage spreading into
    // loose fits; prefer consolidating into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.3 + 0.7 * progress);
    score += 0.15 * pressure * (gap / bin_capacity as f64);

    // Last-chance bonus: if this is the only bin that fits, avoid opening a
    // new bin unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 12.0;
        // But if the fit would leave a gap blocking the next item, weaken bonus.
        if next_item_size > 0 && post_residual < next_item_size {
            score += 8.0;
        }
    }

    // New-bin candidate: opening a fresh bin should only win when the best
    // existing fit is bad. Give the empty bin a moderate default score.
    if bin_residual == bin_capacity {
        // Base cost of a new bin, offset slightly by its flexibility.
        score = 55.0 - 0.2 * mean_residual.min(100.0);
        // Late in the stream, opening bins is cheaper than fragmenting.
        if progress > 0.7 {
            score -= 5.0 * progress;
        }
    }

    // Mild tie-break: prefer bins whose residual is below the mean (denser bins).
    score += 0.05 * (bin_residual as f64 - mean_residual).max(-20.0).min(20.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
