        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = (fitting_bins_count as f64).max(1.0);
        let mut new_bin_penalty = 0.35 * cap + 0.25 * cap * (1.0 - progress);
        if fitting_bins_count >= 2 {
            new_bin_penalty += 0.3 * cap;
