        // If mean residual is large and item is small, opening a bin is wasteful.
        if mean_residual > item_size as f64 {
            new_bin_penalty += 0.2 * (mean_residual - item_size as f64);
        }
        score += new_bin_penalty / pressure.sqrt();
    } else {
        // Mild reward for keeping bins balanced: prefer bins with residual below mean.
        if (bin_residual as f64) < mean_residual {
            score -= 0.1 * (mean_residual - bin_residual as f64);
