        } else if class >= 40 {
            score += 12.0;
        }
    }

    // Nonlinear waste penalty
    score += 15.0 * frac * frac;

    // Strong 2-step lookahead with exact-chain and harmonic chaining
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size <= post_residual {
            let next_post = post_residual - next_item_size;
            if next_post == 0 || next_post % 50 == 0 {
                score -= 20.0;
            } else if next_post < 10 {
                score += 15.0;
            } else {
                score -= 8.0;
            }
        } else {
            let gap = (next_item_size - post_residual) % 50;
            score += 5.0 + gap as f64 * 0.3;
        }
    } else {
        score += post_residual as f64 * 0.5;
    }

    // Last-chance bin: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Tight-bin preference: residual below mean
    let dev = mean_residual - post_residual as f64;
    score += 0.4 * dev;

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        score = 55.0 - 20.0 * progress + 3.0 * open_bins_count as f64;
        if post_residual == 0 {
            score -= 60.0;
        }
        if item_size as f64 > mean_residual {
            score -= 15.0;
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0;
        }
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
    } else {
        score -= 2.0 * (open_bins_count as f64).sqrt();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let frac = post_residual as f64 / cap;
    let progress = step_index as f64 / (total_items.max(1) as f64);

    // Dead-space classification: reward tight fits, penalize awkward gaps
    // (refined: threshold now adapts to item size — larger items tolerate larger gaps)
    let dead_thresh = 10.0 + 0.15 * item_size as f64;
    if post_residual == 0 {
        score -= 75.0 - 10.0 * progress; // perfect fit, stronger late in stream
    } else if (post_residual as f64) < dead_thresh {
        score += 28.0; // near-dead space, slightly stronger penalty
    } else if (post_residual as f64) < dead_thresh * 1.8 {
        score += 8.0;
    }

    // Harmonic class of post_residual: multiples of 50 reuse well
    let class = post_residual % 50;
    if post_residual >= 15 {
        if class == 0 {
            score -= 28.0;
        } else if class <= 20 {
            score -= 10.0;
        } else if class >= 40 {
            score += 14.0;
        }
    }

    // Nonlinear waste penalty (steeper for very small residuals)
    score += 15.0 * frac * frac;
    if post_residual > 0 && post_residual < 5 {
        score += 20.0; // tiny slivers are effectively dead
    }

    // Lookahead coupling (extended: two-step harmony check)
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 55.0;
        } else if next_item_size <= post_residual {
            let next_post = post_residual - next_item_size;
            if next_post == 0 || next_post % 50 == 0 {
                score -= 22.0;
            } else if (next_post as f64) < dead_thresh {
                score += 18.0;
            } else {
                score -= 8.0;
            }
        } else {
            let gap = (next_item_size - post_residual) % 50;
            score += 5.0 + gap as f64 * 0.3;
        }
    } else {
        score += post_residual as f64 * 0.5;
    }

    // Last-chance bin: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        // Base cost grows with number of open bins (pressure to consolidate)
        let mut nb = 55.0 - 20.0 * progress + 3.0 * open_bins_count as f64;
        // Fresh bin is attractive when item is large relative to typical residual
        if item_size as f64 > mean_residual {
            nb -= 18.0;
        }
        // Fresh bin is fine if next item is big
        if next_item_size > 0 && next_item_size >= item_size {
            nb -= 12.0;
        }
        // Discourage opening a new bin for tiny items late in the stream
        if item_size <= 10 && progress > 0.5 {
            nb += 20.0;
        }
        // If many bins can fit the item, prefer consolidation over a fresh bin
        if fitting_bins_count > 2 {
            nb += 12.0 * (fitting_bins_count as f64 - 2.0).min(4.0);
        }
        score = nb;
    } else {
        // Mild reward for consolidating among many open bins
        score -= 2.0 * (open_bins_count as f64).sqrt();
    }

    score
}

